// Cloudflare Workers entry point (wrangler.jsonc `main`). It serves the OpenNext build and adds
// the Cron Triggers that replaced Vercel's crons on 2026-11-17: each schedule calls the same
// route Vercel used to call, with the CRON_SECRET bearer token those routes check.
//
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so this file only
// bundles after a Cloudflare build.
import handler from "./.open-next/worker.js";

const ORIGIN = "https://subscription-tracker.turth00.workers.dev";

// Must match `triggers.crons` in wrangler.jsonc. Times are UTC.
const CRON_ROUTES = {
  "0 18 * * *": "/api/cron/reminders", // 01:00 Bangkok
  "0 14 * * *": "/api/cron/daily-summary", // 21:00 Bangkok
};

const worker = {
  fetch: handler.fetch,

  async scheduled(event, env, ctx) {
    const path = CRON_ROUTES[event.cron];
    if (!path) {
      console.error(`[cron] no route for schedule "${event.cron}"`);
      return;
    }
    const request = new Request(new URL(path, ORIGIN), {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response = await handler.fetch(request, env, ctx);
    console.log(`[cron] ${path} -> ${response.status}`);
    // A failed run shows as an error in the Worker's cron events.
    if (!response.ok) throw new Error(`Cron ${path} returned HTTP ${response.status}`);
  },
};

export default worker;
